import { streamSimple } from "/home/runner/work/pit/pit/node_modules/@earendil-works/pi-ai/dist/api/anthropic-messages.js";
import { normalizeContext } from "/home/runner/work/pit/pit/node_modules/@earendil-works/pi-ai/dist/utils/transcript.js";

const model = {
  id: "aws/anthropic/bedrock-claude-opus-5-5", name: "Opus 5.5", api: "anthropic-messages", provider: "nvidia",
  baseUrl: "https://inference-api.nvidia.com", reasoning: true, input: ["text", "image"],
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: 1050000, maxTokens: 128000,
  compat: { forceAdaptiveThinking: true },
};
const apiKey = process.env.INPUT_API_KEY;
const tools = [{ name: "echo", description: "Echoes text.", parameters: { type: "object", properties: { text: { type: "string" } }, required: ["text"] } }];
const systemPrompt = "You are a terse assistant.";

async function ask(messages, label) {
  const stream = streamSimple(model, normalizeContext({ systemPrompt, messages, tools }), { apiKey, reasoning: "low", maxTokens: 4000 });
  const result = await stream.result();
  const kinds = result.content.map((b) => b.type + (b.type === "thinking" ? `(sig:${Boolean(b.thinkingSignature)})` : ""));
  console.log(label, "->", result.stopReason, result.errorMessage ?? "", JSON.stringify(kinds), JSON.stringify(result.content.filter((b) => b.type === "text").map((b) => b.text)).slice(0, 300));
  return result;
}

const user = (text) => ({ role: "user", content: text, timestamp: Date.now() });
const first = user("Call the echo tool once with text 'hi', then answer with the word it returned.");
const call = await ask([first], "tool call");
const toolCall = call.content.find((b) => b.type === "toolCall");
if (!toolCall) throw new Error("no tool call");
const result = { role: "toolResult", toolCallId: toolCall.id, toolName: "echo", content: [{ type: "text", text: "hi" }], isError: false, timestamp: Date.now() };
const answer = await ask([first, call, result], "answer");

const note = (id) => `[Pit: collapsed echo call · ok · ~40 tokens · originals: session.inspectEntry("${id}"), session.inspectEntry("${id + 1}")]`;
const collapse = (message, id) => ({ ...message, content: [...message.content.filter((b) => b.type !== "toolCall"), { type: "text", text: note(id) }], stopReason: "stop" });
const followUp = user("In one sentence: what did the earlier run do?");

// One collapsed call, with its thinking and signature kept, then the answer: two assistant messages in a row.
await ask([first, collapse(call, 2), answer, followUp], "collapsed+answer (thinking kept)");
// Two collapsed calls in a row, then the answer: three assistant messages in a row.
await ask([first, collapse(call, 2), collapse(call, 4), answer, followUp], "two collapsed+answer (thinking kept)");
// Without thinking, as a run whose turns carried none.
const bare = (m, id) => ({ ...collapse(m, id), content: [{ type: "text", text: note(id) }] });
await ask([first, bare(call, 2), bare(call, 4), answer, followUp], "two collapsed+answer (no thinking)");
// A collapsed run followed by a later run's live call, as the next request after a collapse sees.
const second = user("Call echo again with text 'yo'.");
const again = await ask([first, collapse(call, 2), answer, second], "live call after collapsed run");
const againCall = again.content.find((b) => b.type === "toolCall");
if (againCall) {
  await ask([first, collapse(call, 2), answer, second, again, { ...result, toolCallId: againCall.id, content: [{ type: "text", text: "yo" }] }], "result after collapsed run");
}
